-- Replaces all previous interaction data with the supplied PrEP workbook.
-- Run once against the application database. Re-running resets interaction edits.
SET NAMES utf8mb4;
DROP TABLE IF EXISTS `interaksi_obat_prep_import`;
CREATE TABLE `interaksi_obat_prep_import` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `no_sumber` varchar(20) DEFAULT NULL,
  `nama_obat` varchar(200) NOT NULL,
  `level_tdf` varchar(200) NOT NULL,
  `level_3tc` varchar(200) NOT NULL,
  `mekanisme` text NOT NULL,
  `rekomendasi` text NOT NULL,
  `catatan` text NOT NULL,
  `referensi` varchar(100) DEFAULT NULL,
  `urutan` int(11) NOT NULL DEFAULT 0,
  `status` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `interaksi_obat_nama_unique` (`nama_obat`),
  KEY `interaksi_obat_status_urutan_idx` (`status`,`urutan`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


-- Replace only after the complete new dataset has been inserted successfully.
DROP TABLE IF EXISTS `interaksi_obat`;
RENAME TABLE `interaksi_obat_prep_import` TO `interaksi_obat`;
