INSERT INTO `interaksi_obat_prep_import`
(`no_sumber`,`nama_obat`,`level_tdf`,`level_3tc`,`mekanisme`,`rekomendasi`,`referensi`,`catatan`,`urutan`,`status`,`created_at`,`updated_at`) VALUES
('1','Kotrimoksazol (TMP 160 mg/SMX 800 mg)','Minor – tidak ada interaksi langsung bermakna','Minor – tidak ada interaksi langsung bermakna','TDF: TMP dapat menaikkan kreatinin serum dengan menghambat sekresi tubular; TMP-SMX dan TDF dapat sama-sama menuntut pemantauan ginjal. Bukan bukti bahwa kadar TDF pasti meningkat.  ||  Lamivudin: 3TC dieliminasi terutama melalui ginjal; penurunan klirens ginjal dapat meningkatkan paparan 3TC. TMP-SMX sendiri dapat menaikkan kreatinin tanpa penurunan GFR sejati.','TDF: Pantau kreatinin/eCrCl dan kalium pada CKD, dehidrasi, usia lanjut atau obat nefrotoksik/hiperkalemia lain. Sesuaikan 3TC bila gangguan ginjal sesuai label.  ||  Lamivudin: Pantau kreatinin/eCrCl dan kalium pada CKD, dehidrasi, usia lanjut atau obat nefrotoksik/hiperkalemia lain. Sesuaikan 3TC bila gangguan ginjal sesuai label.','S1;S2;S3','',1,1,NOW(),NOW()),
('2','Kotrimoksazol suspensi pediatrik','Moderate – perlu pemantauan','Minor – tidak ada interaksi langsung bermakna','TDF: TMP dapat memengaruhi sekresi kreatinin; penilaian eGFR anak harus memakai rumus pediatrik yang sesuai.  ||  Lamivudin: 3TC dieliminasi renal; dosis pediatrik dan penyesuaian harus mengikuti berat badan/luas permukaan tubuh dan fungsi ginjal.','TDF: Jangan gunakan dosis dewasa untuk anak; pantau fungsi ginjal/kalium berdasarkan kondisi klinis.  ||  Lamivudin: Jangan gunakan dosis dewasa untuk anak; pantau fungsi ginjal/kalium berdasarkan kondisi klinis.','S1;S2;S3','',2,1,NOW(),NOW()),
('3','Isoniazid (INH)','Minor – tidak ada interaksi langsung bermakna','Minor – tidak ada interaksi langsung bermakna','TDF: INH terutama mengalami asetilasi/metabolisme hepatik; TDF dieliminasi ginjal dan bukan substrat CYP.  ||  Lamivudin: 3TC terutama diekskresikan ginjal dan tidak bergantung CYP; tidak ada jalur interaksi utama dengan INH.','TDF: Pantau gejala hepatotoksisitas INH; berikan piridoksin sesuai indikasi. Evaluasi obat lain yang dapat hepatotoksik.  ||  Lamivudin: Pantau gejala hepatotoksisitas INH; berikan piridoksin sesuai indikasi. Evaluasi obat lain yang dapat hepatotoksik.','S1;S4;S5','',3,1,NOW(),NOW()),
('4','Isoniazid + Rifapentin (3HP)','Minor – tidak ada interaksi bermakna yang diharapkan','Minor – tidak ada interaksi bermakna yang diharapkan','TDF: NIH mencatat AUC tenofovir tidak berubah bermakna dengan rifapentin; TDF tidak bergantung CYP.  ||  Lamivudin: NIH menyatakan kadar 3TC diperkirakan tidak berubah dengan rifapentin.','TDF: Tidak perlu penyesuaian TDF/3TC rutin; tetap cek interaksi rifapentin dengan semua obat lain, terutama ARV selain TDF/3TC dan kontrasepsi hormonal.  ||  Lamivudin: Tidak perlu penyesuaian TDF/3TC rutin; tetap cek interaksi rifapentin dengan semua obat lain, terutama ARV selain TDF/3TC dan kontrasepsi hormonal.','S1;S4;S5','',4,1,NOW(),NOW()),
('5','Isoniazid + Rifampisin (3HR)','Minor – tidak ada interaksi bermakna yang diharapkan','Minor – tidak ada interaksi bermakna yang diharapkan','TDF: Rifampisin penginduksi enzim/transporter, tetapi NIH mencatat AUC tenofovir tidak berubah bermakna; TDF bukan substrat CYP utama.  ||  Lamivudin: NIH mencatat 3TC tidak berubah bermakna dengan rifampisin.','TDF: TDF/3TC umumnya tidak perlu penyesuaian; rifampisin dapat menurunkan kadar obat lain (mis. hormon, sebagian ARV, azol), sehingga cek seluruh regimen.  ||  Lamivudin: TDF/3TC umumnya tidak perlu penyesuaian; rifampisin dapat menurunkan kadar obat lain (mis. hormon, sebagian ARV, azol), sehingga cek seluruh regimen.','S1;S4;S5','',5,1,NOW(),NOW()),
('6','KDT fase intensif (Rifampisin/INH/Pirazinamid/Etambutol)','Minor – tidak ada interaksi langsung bermakna','Minor – tidak ada interaksi langsung bermakna','TDF: TDF diekskresikan ginjal; rifampisin tidak menurunkan paparan TDF secara bermakna menurut tabel NIH. Etambutol juga perlu perhatian pada gangguan ginjal.  ||  Lamivudin: 3TC renal; dosis dapat perlu disesuaikan jika fungsi ginjal turun. Rifampisin bukan penginduksi yang menurunkan 3TC.','TDF: Pantau fungsi hati karena INH/PZA dan fungsi ginjal karena TDF/etambutol. Jangan mengekstrapolasi hasil ini ke ARV lain: rifampisin berinteraksi penting dengan banyak ARV.  ||  Lamivudin: Pantau fungsi hati karena INH/PZA dan fungsi ginjal karena TDF/etambutol. Jangan mengekstrapolasi hasil ini ke ARV lain: rifampisin berinteraksi penting dengan banyak ARV.','S1;S4;S5','',6,1,NOW(),NOW()),
('7','KDT fase lanjutan (Rifampisin/INH)','Minor – tidak ada interaksi langsung bermakna','Minor – tidak ada interaksi langsung bermakna','TDF: Rifampisin tidak mengubah AUC tenofovir secara bermakna pada data NIH.  ||  Lamivudin: 3TC tidak bergantung CYP dan tidak diperkirakan terpengaruh induksi rifampisin.','TDF: Pantau hati dan ginjal; review interaksi rifampisin dengan semua obat lain, khususnya kontrasepsi hormonal dan ARV lain.  ||  Lamivudin: Pantau hati dan ginjal; review interaksi rifampisin dengan semua obat lain, khususnya kontrasepsi hormonal dan ARV lain.','S1;S4;S5','',7,1,NOW(),NOW()),
('8','Nistatin suspensi oral','Minor – tidak ada interaksi bermakna yang diharapkan','Minor – tidak ada interaksi bermakna yang diharapkan','TDF: Nistatin oral diserap sistemik sangat minimal sehingga tidak memengaruhi eliminasi TDF.  ||  Lamivudin: Absorpsi sistemik nistatin minimal; tidak ada mekanisme yang memengaruhi klirens 3TC.','TDF: Dapat digunakan bersama; interaksi klinis bermakna tidak diharapkan.  ||  Lamivudin: Dapat digunakan bersama; interaksi klinis bermakna tidak diharapkan.','S1;S6','',8,1,NOW(),NOW()),
('9','Flukonazol','Minor – tidak ada interaksi langsung bermakna','Minor – tidak ada interaksi bermakna yang diharapkan','TDF: Flukonazol menghambat CYP, tetapi TDF bukan substrat CYP utama; potensi interaksi melalui metabolisme CYP rendah.  ||  Lamivudin: 3TC tidak dimetabolisme bermakna oleh CYP; eliminasi renal.','TDF: Tidak perlu penyesuaian TDF/3TC rutin; sesuaikan dosis flukonazol pada gangguan ginjal sesuai label dan periksa obat lain yang berinteraksi.  ||  Lamivudin: Tidak perlu penyesuaian TDF/3TC rutin; sesuaikan dosis flukonazol pada gangguan ginjal sesuai label dan periksa obat lain yang berinteraksi.','S1;S6;S7','',9,1,NOW(),NOW()),
('10','Amfoterisin B','Moderate – nefrotoksisitas aditif','Minor – tidak ada interaksi langsung bermakna','TDF: Amfoterisin B dapat menyebabkan vasokonstriksi renal dan cedera tubulus; TDF dapat menyebabkan toksisitas tubulus proksimal. Risiko cedera ginjal dapat bertambah.  ||  Lamivudin: 3TC diekskresikan ginjal; penurunan GFR mengurangi klirens 3TC.','TDF: Kombinasi bila diperlukan harus di bawah supervisi spesialis; pantau kreatinin/eCrCl, elektrolit (K/Mg/fosfat), urinalisis dan hidrasi. Evaluasi alternatif TDF bila risiko tinggi.  ||  Lamivudin: Kombinasi bila diperlukan harus di bawah supervisi spesialis; pantau kreatinin/eCrCl, elektrolit (K/Mg/fosfat), urinalisis dan hidrasi. Evaluasi alternatif TDF bila risiko tinggi.','S1;S2;S6;S7','',10,1,NOW(),NOW()),
('11','Itrakonazol','Minor – tidak ada interaksi langsung bermakna','Minor – tidak ada interaksi langsung bermakna','TDF: Itrakonazol menghambat CYP3A/P-gp; TDF tidak bergantung CYP3A sehingga perubahan paparan TDF tidak diharapkan.  ||  Lamivudin: 3TC tidak dimetabolisme oleh CYP3A; eliminasi renal.','TDF: Tidak perlu penyesuaian TDF/3TC; itrakonazol memiliki banyak interaksi dengan obat lain dan potensi hepatotoksisitas.  ||  Lamivudin: Tidak perlu penyesuaian TDF/3TC; itrakonazol memiliki banyak interaksi dengan obat lain dan potensi hepatotoksisitas.','S1;S6;S7','',11,1,NOW(),NOW()),
('12','Ketokonazol oral','Mayor – hindari/alternatif','Mayor – hindari/alternatif','TDF: Inhibisi CYP oleh ketokonazol tidak diperkirakan mengubah eliminasi renal TDF.  ||  Lamivudin: 3TC tidak bergantung CYP untuk eliminasi.','TDF: Ketokonazol oral sebaiknya dihindari bila tersedia alternatif karena hepatotoksisitas dan interaksi luas; bukan karena interaksi langsung TDF/3TC.  ||  Lamivudin: Ketokonazol oral sebaiknya dihindari bila tersedia alternatif karena hepatotoksisitas dan interaksi luas; bukan karena interaksi langsung TDF/3TC.','S1;S6;S7','',12,1,NOW(),NOW()),
('13','Tenofovir TDF 300 mg dari produk lain','Mayor – duplikasi bahan aktif','Minor – tidak ada interaksi langsung bermakna','TDF: Duplikasi bahan aktif meningkatkan paparan tenofovir dan risiko toksisitas ginjal/tulang tanpa manfaat pencegahan tambahan.  ||  Lamivudin: Lamivudine tidak mencegah duplikasi tenofovir; kombinasi dapat meningkatkan beban obat tanpa indikasi.','TDF: Verifikasi apakah TDF 300 mg yang tercantum adalah komponen PrEP yang sama. Jangan berikan dua produk TDF bersamaan kecuali keputusan spesialis.  ||  Lamivudin: Verifikasi apakah TDF 300 mg yang tercantum adalah komponen PrEP yang sama. Jangan berikan dua produk TDF bersamaan kecuali keputusan spesialis.','S1;S2;S3','',13,1,NOW(),NOW()),
('14','Sofosbuvir + Daclatasvir','Moderate – perlu pemantauan','Minor – tidak ada interaksi langsung bermakna','TDF: Sofosbuvir/daclatasvir bukan induktor CYP kuat; risiko TDF lebih relevan bila ada ritonavir/cobicistat atau gangguan ginjal dalam regimen kompleks.  ||  Lamivudin: 3TC tidak memiliki jalur metabolisme utama yang bertumpang tindih dengan SOF/DCV.','TDF: Cek regimen HCV lengkap di Liverpool; pantau ginjal bila TDF digunakan dengan booster atau faktor risiko. Perhatikan interaksi DAA dengan obat lain.  ||  Lamivudin: Cek regimen HCV lengkap di Liverpool; pantau ginjal bila TDF digunakan dengan booster atau faktor risiko. Perhatikan interaksi DAA dengan obat lain.','S1;S7;S8','',14,1,NOW(),NOW()),
('15','Sofosbuvir / Velpatasvir','Moderate – paparan TDF dapat meningkat','Minor – tidak ada interaksi langsung bermakna','TDF: Velpatasvir menghambat transporter P-gp/BCRP; dapat meningkatkan tenofovir dari TDF. Risiko lebih besar bila ada booster farmakokinetik.  ||  Lamivudin: 3TC tidak diharapkan mengalami perubahan bermakna akibat velpatasvir.','TDF: Verifikasi regimen lengkap dan label; pantau fungsi ginjal bila TDF dipakai, khususnya dengan booster atau CKD. Pertimbangkan alternatif setelah penilaian klinis.  ||  Lamivudin: Verifikasi regimen lengkap dan label; pantau fungsi ginjal bila TDF dipakai, khususnya dengan booster atau CKD. Pertimbangkan alternatif setelah penilaian klinis.','S1;S7;S8','',15,1,NOW(),NOW()),
('16','Benzatin benzilpenisilin G','Minor – tidak ada interaksi bermakna yang diharapkan','Minor – tidak ada interaksi bermakna yang diharapkan','TDF: Tidak ada kompetisi metabolisme yang diketahui; eliminasi penisilin tidak menimbulkan interaksi klinis mapan dengan TDF.  ||  Lamivudin: Tidak ada mekanisme interaksi spesifik; 3TC renal tetapi penisilin benzatin tidak dikenal mengubah klirensnya.','TDF: Dapat digunakan bersama; dosis dan regimen mengikuti stadium sifilis dan pedoman IMS.  ||  Lamivudin: Dapat digunakan bersama; dosis dan regimen mengikuti stadium sifilis dan pedoman IMS.','S1;S7','',16,1,NOW(),NOW()),
('17','Sefiksim','Minor – tidak ada interaksi bermakna yang diharapkan','Minor – tidak ada interaksi bermakna yang diharapkan','TDF: Sefiksim dieliminasi sebagian melalui ginjal; tidak ada kompetisi transporter klinis yang mapan dengan TDF.  ||  Lamivudin: Kedua obat memiliki eliminasi renal, tetapi interaksi kompetitif klinis tidak terbukti.','TDF: Dapat digunakan bersama; dosis sefiksim dan 3TC perlu ditinjau pada gangguan ginjal berat.  ||  Lamivudin: Dapat digunakan bersama; dosis sefiksim dan 3TC perlu ditinjau pada gangguan ginjal berat.','S1;S7','',17,1,NOW(),NOW()),
('18','Seftriakson','Minor – tidak ada interaksi bermakna yang diharapkan','Minor – tidak ada interaksi bermakna yang diharapkan','TDF: Tidak ada jalur metabolisme atau transporter yang relevan dengan TDF.  ||  Lamivudin: Tidak ada mekanisme interaksi spesifik dengan eliminasi 3TC.','TDF: Dapat digunakan bersama sesuai indikasi; perhatikan alergi dan pedoman dosis gonore terbaru.  ||  Lamivudin: Dapat digunakan bersama sesuai indikasi; perhatikan alergi dan pedoman dosis gonore terbaru.','S1;S7','',18,1,NOW(),NOW()),
('19','Azitromisin','Minor – tidak ada interaksi langsung bermakna','Minor – tidak ada interaksi langsung bermakna','TDF: Azitromisin memiliki efek inhibisi CYP rendah; TDF bukan substrat CYP.  ||  Lamivudin: 3TC tidak dimetabolisme CYP.','TDF: Dapat digunakan bersama; nilai risiko QT dan interaksi azitromisin dengan obat lain bila relevan.  ||  Lamivudin: Dapat digunakan bersama; nilai risiko QT dan interaksi azitromisin dengan obat lain bila relevan.','S1;S6;S7','',19,1,NOW(),NOW()),
('20','Doksisiklin','Minor – tidak ada interaksi bermakna yang diharapkan','Minor – tidak ada interaksi bermakna yang diharapkan','TDF: Tidak ada mekanisme interaksi dengan TDF; kation mineral dapat mengurangi absorpsi doksisiklin, bukan TDF.  ||  Lamivudin: 3TC tidak mengkelat doksisiklin dan tidak memengaruhi absorpsinya.','TDF: Dapat digunakan bersama; pisahkan doksisiklin dari Fe/Ca/Mg/Zn sesuai label doksisiklin. Catatan ini bukan interaksi PrEP.  ||  Lamivudin: Dapat digunakan bersama; pisahkan doksisiklin dari Fe/Ca/Mg/Zn sesuai label doksisiklin. Catatan ini bukan interaksi PrEP.','S1;S7','',20,1,NOW(),NOW()),
('21','Asiklovir','Moderate – risiko ginjal','Minor – tidak ada interaksi langsung bermakna','TDF: Asiklovir dieliminasi ginjal dan dapat menyebabkan kristaluria/cedera ginjal; TDF berpotensi toksik pada tubulus. Risiko bersifat terutama farmakodinamik/renal.  ||  Lamivudin: 3TC diekskresikan ginjal; penurunan GFR meningkatkan paparan.','TDF: Pastikan hidrasi; pantau fungsi ginjal pada dosis tinggi/IV atau pasien berisiko; sesuaikan dosis asiklovir dan 3TC sesuai eCrCl.  ||  Lamivudin: Pastikan hidrasi; pantau fungsi ginjal pada dosis tinggi/IV atau pasien berisiko; sesuaikan dosis asiklovir dan 3TC sesuai eCrCl.','S1;S2;S3','',21,1,NOW(),NOW()),
('22','Metronidazol','Mayor – hindari/alternatif','Mayor – hindari/alternatif','TDF: Metronidazol dimetabolisme hati; TDF tidak bergantung CYP.  ||  Lamivudin: 3TC terutama diekskresikan ginjal; tidak ada jalur interaksi utama.','TDF: Dapat digunakan bersama. Hindari alkohol selama terapi; informasi produk umumnya menyarankan menghindari selama 48–72 jam setelah dosis terakhir karena reaksi mirip-disulfiram/peringatan label, walau bukti klinis diperdebatkan.  ||  Lamivudin: Dapat digunakan bersama. Hindari alkohol selama terapi; informasi produk umumnya menyarankan menghindari selama 48–72 jam setelah dosis terakhir karena reaksi mirip-disulfiram/peringatan label, walau bukti klinis diperdebatkan.','S1;S7;S9','',22,1,NOW(),NOW()),
('23','Amlodipin','Minor – tidak ada interaksi langsung bermakna','Minor – tidak ada interaksi langsung bermakna','TDF: TDF tidak menghambat CYP yang relevan bagi obat-obat ini; perhatian klinis adalah kondisi ginjal, tekanan darah dan elektrolit.  ||  Lamivudin: 3TC tidak menghambat/ menginduksi CYP; jika fungsi ginjal menurun, klirens 3TC turun.','TDF: Dapat digunakan bersama TDF/3TC. CCB; dapat meningkat dengan PI/booster, tetapi bukan TDF/3TC. Pantau eGFR/kreatinin dan kalium sesuai obat dan faktor risiko; periksa interaksi terpisah bila ada PI/booster dalam regimen ART.  ||  Lamivudin: Dapat digunakan bersama TDF/3TC. CCB; dapat meningkat dengan PI/booster, tetapi bukan TDF/3TC. Pantau eGFR/kreatinin dan kalium sesuai obat dan faktor risiko; periksa interaksi terpisah bila ada PI/booster dalam regimen ART.','S1;S2;S3;S7','',23,1,NOW(),NOW()),
('24','Kaptopril','Minor – tidak ada interaksi langsung bermakna','Minor – tidak ada interaksi langsung bermakna','TDF: TDF tidak menghambat CYP yang relevan bagi obat-obat ini; perhatian klinis adalah kondisi ginjal, tekanan darah dan elektrolit.  ||  Lamivudin: 3TC tidak menghambat/ menginduksi CYP; jika fungsi ginjal menurun, klirens 3TC turun.','TDF: Dapat digunakan bersama TDF/3TC. ACE inhibitor; pantau kreatinin dan kalium. Pantau eGFR/kreatinin dan kalium sesuai obat dan faktor risiko; periksa interaksi terpisah bila ada PI/booster dalam regimen ART.  ||  Lamivudin: Dapat digunakan bersama TDF/3TC. ACE inhibitor; pantau kreatinin dan kalium. Pantau eGFR/kreatinin dan kalium sesuai obat dan faktor risiko; periksa interaksi terpisah bila ada PI/booster dalam regimen ART.','S1;S2;S3;S7','',24,1,NOW(),NOW()),
('25','Lisinopril','Minor – tidak ada interaksi langsung bermakna','Minor – tidak ada interaksi langsung bermakna','TDF: TDF tidak menghambat CYP yang relevan bagi obat-obat ini; perhatian klinis adalah kondisi ginjal, tekanan darah dan elektrolit.  ||  Lamivudin: 3TC tidak menghambat/ menginduksi CYP; jika fungsi ginjal menurun, klirens 3TC turun.','TDF: Dapat digunakan bersama TDF/3TC. ACE inhibitor; pantau kreatinin dan kalium. Pantau eGFR/kreatinin dan kalium sesuai obat dan faktor risiko; periksa interaksi terpisah bila ada PI/booster dalam regimen ART.  ||  Lamivudin: Dapat digunakan bersama TDF/3TC. ACE inhibitor; pantau kreatinin dan kalium. Pantau eGFR/kreatinin dan kalium sesuai obat dan faktor risiko; periksa interaksi terpisah bila ada PI/booster dalam regimen ART.','S1;S2;S3;S7','',25,1,NOW(),NOW()),
('26','Hidroklorotiazid (HCT)','Minor – tidak ada interaksi langsung bermakna','Minor – tidak ada interaksi langsung bermakna','TDF: TDF tidak menghambat CYP yang relevan bagi obat-obat ini; perhatian klinis adalah kondisi ginjal, tekanan darah dan elektrolit.  ||  Lamivudin: 3TC tidak menghambat/ menginduksi CYP; jika fungsi ginjal menurun, klirens 3TC turun.','TDF: Dapat digunakan bersama TDF/3TC. Diuretik; dehidrasi/hipovolemia dapat memengaruhi ginjal. Pantau eGFR/kreatinin dan kalium sesuai obat dan faktor risiko; periksa interaksi terpisah bila ada PI/booster dalam regimen ART.  ||  Lamivudin: Dapat digunakan bersama TDF/3TC. Diuretik; dehidrasi/hipovolemia dapat memengaruhi ginjal. Pantau eGFR/kreatinin dan kalium sesuai obat dan faktor risiko; periksa interaksi terpisah bila ada PI/booster dalam regimen ART.','S1;S2;S3;S7','',26,1,NOW(),NOW()),
('27','Kandesartan','Minor – tidak ada interaksi langsung bermakna','Minor – tidak ada interaksi langsung bermakna','TDF: TDF tidak menghambat CYP yang relevan bagi obat-obat ini; perhatian klinis adalah kondisi ginjal, tekanan darah dan elektrolit.  ||  Lamivudin: 3TC tidak menghambat/ menginduksi CYP; jika fungsi ginjal menurun, klirens 3TC turun.','TDF: Dapat digunakan bersama TDF/3TC. ARB; pantau kreatinin dan kalium. Pantau eGFR/kreatinin dan kalium sesuai obat dan faktor risiko; periksa interaksi terpisah bila ada PI/booster dalam regimen ART.  ||  Lamivudin: Dapat digunakan bersama TDF/3TC. ARB; pantau kreatinin dan kalium. Pantau eGFR/kreatinin dan kalium sesuai obat dan faktor risiko; periksa interaksi terpisah bila ada PI/booster dalam regimen ART.','S1;S2;S3;S7','',27,1,NOW(),NOW()),
('28','Metformin','Minor – tidak ada interaksi langsung bermakna','Minor – tidak ada interaksi langsung bermakna','TDF: Biguanid tidak memiliki jalur metabolisme yang dipengaruhi TDF secara klinis; fungsi ginjal tetap penting terutama untuk metformin.  ||  Lamivudin: 3TC dan metformin sama-sama bergantung pada fungsi ginjal, tetapi interaksi kompetitif bermakna belum terbukti. Gangguan ginjal dapat meningkatkan paparan 3TC dan risiko metformin.','TDF: Dapat digunakan bersama; pantau eGFR. Pada metformin, ikuti batas eGFR dan aturan penghentian saat penyakit akut/dehidrasi. Pantau glukosa sesuai standar.  ||  Lamivudin: Dapat digunakan bersama; pantau eGFR. Pada metformin, ikuti batas eGFR dan aturan penghentian saat penyakit akut/dehidrasi. Pantau glukosa sesuai standar.','S1;S2;S3;S7','',28,1,NOW(),NOW()),
('29','Glimepirid','Minor – tidak ada interaksi langsung bermakna','Minor – tidak ada interaksi langsung bermakna','TDF: Sulfonilurea tidak memiliki jalur metabolisme yang dipengaruhi TDF secara klinis; fungsi ginjal tetap penting terutama untuk metformin.  ||  Lamivudin: 3TC dan metformin sama-sama bergantung pada fungsi ginjal, tetapi interaksi kompetitif bermakna belum terbukti. Gangguan ginjal dapat meningkatkan paparan 3TC dan risiko metformin.','TDF: Dapat digunakan bersama; pantau eGFR. Pada metformin, ikuti batas eGFR dan aturan penghentian saat penyakit akut/dehidrasi. Pantau glukosa sesuai standar.  ||  Lamivudin: Dapat digunakan bersama; pantau eGFR. Pada metformin, ikuti batas eGFR dan aturan penghentian saat penyakit akut/dehidrasi. Pantau glukosa sesuai standar.','S1;S2;S3;S7','',29,1,NOW(),NOW()),
